async function getJson<T>(url: string) {
  try {
    const res = await fetch(url);
    const body = await res.json();
    return res.ok
      ? { ok: true as const, data: body as T }
      : { ok: false as const, error: String(body?.error ?? `HTTP ${res.status}`) };
  } catch (e) {
    return { ok: false as const, error: (e as Error).message };
  }
}

const PAGE_SIZE = 50;

export function OrderList() {
  const [orders, setOrders] = useState<Order[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    getJson<{ items: Order[] }>(`/api/orders?limit=${PAGE_SIZE}`).then((r) => {
      setLoading(false);
      if (!r.ok) {
        toast.error(`加载失败：${r.error}`);
        return;
      }
      setOrders(r.data.items);
    });
  }, []);

  return (
    <section>
      <h3>订单 · 共 {orders.length} 条</h3>
      <p className="hint">最多显示最近 100 条订单。</p>
      {loading ? <Spinner /> : orders.length ? <OrderTable rows={orders} /> : <Empty text="暂无订单" />}
    </section>
  );
}
